prologue:
static int g_demo_sel_script = -1;
static int g_demo_sel_move = 0;
static int g_demo_sel_sub = 0;
static int g_demo_last_added = -1;
static int g_demo_input_dirty = 0;

static MOD_UNUSED int demo_resolve_script(int script) {
    int cur;
    if (script >= 0) return script;
    if (API->demo != 0) {
        cur = API->demo->Current(SELF);
        if (cur >= 0) return cur;
    }
    if (g_demo_sel_script >= 0) return g_demo_sel_script;
    if (g_demo_last_added >= 0) return g_demo_last_added;
    return 0;
}

static MOD_UNUSED int demo_resolve_move(int move) {
    int cur;
    if (move >= 0) return move;
    if (API->demo != 0) {
        cur = API->demo->MoveIndex(SELF);
        if (cur >= 0) return cur;
    }
    return g_demo_sel_move >= 0 ? g_demo_sel_move : 0;
}

static MOD_UNUSED int demo_resolve_sub(int index) {
    return index >= 0 ? index : (g_demo_sel_sub >= 0 ? g_demo_sel_sub : 0);
}

static MOD_UNUSED void demo_select_cursor(int script, int move, int sub) {
    g_demo_sel_script = script;
    g_demo_sel_move = move;
    g_demo_sel_sub = sub;
}

static MOD_UNUSED int demo_last_added(void) {
    return g_demo_last_added;
}

static MOD_UNUSED float demo_break_time(int script) {
    return API->demo != 0 ? API->demo->GetBreakTime(SELF, demo_resolve_script(script)) : 0.0f;
}

static MOD_UNUSED void demo_set_break_time(int script, float seconds) {
    if (API->demo != 0) API->demo->SetBreakTime(SELF, demo_resolve_script(script), seconds);
}

static MOD_UNUSED int demo_move_count(int script) {
    return API->demo != 0 ? API->demo->MoveCount(SELF, demo_resolve_script(script)) : 0;
}

static MOD_UNUSED int demo_read_move(AmodDemoMove* out) {
    if (API->demo == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->demo->GetMove(SELF, demo_resolve_script(-1), demo_resolve_move(-1), out);
}

static MOD_UNUSED float demo_move_num(int which) {
    AmodDemoMove m;
    if (demo_read_move(&m) == 0) return 0.0f;
    return which == 0 ? m.pause : m.endCoord;
}

static MOD_UNUSED int demo_move_int(int which) {
    AmodDemoMove m;
    if (demo_read_move(&m) == 0) return 0;
    switch (which) {
        case 0: return m.horizontal;
        case 1: return m.vertical;
        case 2: return m.jump;
        case 3: return m.timeCount;
        case 4: return m.viewCount;
        case 5: return m.camCount;
        default: return 0;
    }
}

static MOD_UNUSED void demo_set_move(int script, int move, float pause, int horz, int vert, int jump, float endCoord) {
    AmodDemoMove m;
    if (API->demo == 0) return;
    memset(&m, 0, sizeof m);
    m.structSize = sizeof m;
    m.pause = pause;
    m.horizontal = horz;
    m.vertical = vert;
    m.jump = jump;
    m.endCoord = endCoord;
    API->demo->SetMove(SELF, demo_resolve_script(script), demo_resolve_move(move), &m);
}

static MOD_UNUSED int demo_read_cam(int isView, AmodDemoCamera* out) {
    int s, m, idx;
    if (API->demo == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    s = demo_resolve_script(-1);
    m = demo_resolve_move(-1);
    idx = demo_resolve_sub(-1);
    return isView ? API->demo->GetView(SELF, s, m, idx, out) : API->demo->GetCamera(SELF, s, m, idx, out);
}

static MOD_UNUSED float demo_cam_num(int isView, int which) {
    AmodDemoCamera c;
    if (demo_read_cam(isView, &c) == 0) return 0.0f;
    switch (which) {
        case 0: return c.position[0];
        case 1: return c.position[1];
        case 2: return c.position[2];
        case 3: return c.speed[0];
        case 4: return c.speed[1];
        case 5: return c.speed[2];
        case 6: return c.time;
        default: return 0.0f;
    }
}

static MOD_UNUSED int demo_cam_auto(int isView) {
    AmodDemoCamera c;
    return demo_read_cam(isView, &c) != 0 ? c.giveBack : 0;
}

static MOD_UNUSED void demo_write_cam(int isView, int script, int move, int index, float x, float y, float z, float sx, float sy, float sz, float dur, int giveBack) {
    AmodDemoCamera c;
    int s, m, idx;
    if (API->demo == 0) return;
    memset(&c, 0, sizeof c);
    c.structSize = sizeof c;
    c.position[0] = x; c.position[1] = y; c.position[2] = z;
    c.speed[0] = sx; c.speed[1] = sy; c.speed[2] = sz;
    c.time = dur > 0.001f ? dur : 0.01f;
    c.giveBack = giveBack;
    s = demo_resolve_script(script);
    m = demo_resolve_move(move);
    idx = demo_resolve_sub(index);
    if (isView) API->demo->SetView(SELF, s, m, idx, &c);
    else API->demo->SetCamera(SELF, s, m, idx, &c);
}

static MOD_UNUSED float demo_time_num(int which) {
    AmodDemoTime t;
    if (API->demo == 0) return 0.0f;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    if (API->demo->GetTime(SELF, demo_resolve_script(-1), demo_resolve_move(-1), demo_resolve_sub(-1), &t) == 0) return 0.0f;
    if (which == 0) return t.pause;
    if (which == 1) return t.factor;
    return t.time;
}

static MOD_UNUSED void demo_set_time(int script, int move, int index, float pause, float factor, float dur) {
    AmodDemoTime t;
    if (API->demo == 0) return;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    t.pause = pause;
    t.factor = factor;
    t.time = dur;
    API->demo->SetTime(SELF, demo_resolve_script(script), demo_resolve_move(move), demo_resolve_sub(index), &t);
}

static MOD_UNUSED int demo_has_cam_start(int script) {
    float pos[3], view[3];
    return API->demo != 0 && API->demo->GetCameraStart(SELF, demo_resolve_script(script), pos, view) != 0;
}

static MOD_UNUSED float demo_cam_start_num(int isView, int axis) {
    float pos[3] = { 0.0f, 0.0f, 0.0f }, view[3] = { 0.0f, 0.0f, 0.0f };
    if (axis < 0 || axis > 2 || API->demo == 0) return 0.0f;
    if (API->demo->GetCameraStart(SELF, demo_resolve_script(-1), pos, view) == 0) return 0.0f;
    return isView ? view[axis] : pos[axis];
}

static MOD_UNUSED void demo_set_cam_start(int script, float cx, float cy, float cz, float vx, float vy, float vz) {
    float pos[3], view[3];
    if (API->demo == 0) return;
    pos[0] = cx; pos[1] = cy; pos[2] = cz;
    view[0] = vx; view[1] = vy; view[2] = vz;
    API->demo->SetCameraStart(SELF, demo_resolve_script(script), pos, view);
}

static MOD_UNUSED int demo_has_place(int script) {
    AmodDemoPlace p;
    if (API->demo == 0) return 0;
    memset(&p, 0, sizeof p);
    p.structSize = sizeof p;
    return API->demo->GetPlace(SELF, demo_resolve_script(script), &p) != 0;
}

static MOD_UNUSED int demo_place_int(int which) {
    AmodDemoPlace p;
    if (API->demo == 0) return 0;
    memset(&p, 0, sizeof p);
    p.structSize = sizeof p;
    if (API->demo->GetPlace(SELF, demo_resolve_script(-1), &p) == 0) return 0;
    if (which == 0) return p.playerX;
    if (which == 1) return p.playerY;
    if (which == 2) return p.roomX;
    return p.roomY;
}

static MOD_UNUSED void demo_play(int script) {
    if (API->demo != 0) API->demo->Play(SELF, demo_resolve_script(script));
}

static MOD_UNUSED void demo_add_file(const char* path) {
    int idx;
    if (API->demo == 0 || path == 0 || path[0] == 0) return;
    idx = API->demo->Add(SELF, path);
    if (idx >= 0) {
        g_demo_last_added = idx;
        g_demo_sel_script = idx;
        g_demo_sel_move = 0;
        g_demo_sel_sub = 0;
    }
}

static MOD_UNUSED void demo_remove(int script) {
    int target;
    if (API->demo == 0) return;
    target = script >= 0 ? script : g_demo_last_added;
    if (target < 0) return;
    if (API->demo->Remove(SELF, target) != 0) {
        if (g_demo_last_added == target) g_demo_last_added = -1;
        if (g_demo_sel_script == target) g_demo_sel_script = -1;
    }
}

static MOD_UNUSED void demo_create_empty(void) {
    int idx;
    if (API->demo == 0) return;
    idx = API->demo->Create(SELF);
    if (idx >= 0) {
        g_demo_last_added = idx;
        g_demo_sel_script = idx;
        g_demo_sel_move = 0;
        g_demo_sel_sub = 0;
    }
}

static MOD_UNUSED void demo_append_move(int script, float pause, int horz, int vert, int jump, float endCoord) {
    AmodDemoMove m;
    int idx;
    if (API->demo == 0) return;
    memset(&m, 0, sizeof m);
    m.structSize = sizeof m;
    m.pause = pause;
    m.horizontal = horz;
    m.vertical = vert;
    m.jump = jump;
    m.endCoord = endCoord;
    idx = API->demo->AddMove(SELF, demo_resolve_script(script), &m);
    if (idx >= 0) { g_demo_sel_move = idx; g_demo_sel_sub = 0; }
}

static MOD_UNUSED void demo_append_cam(int isView, int script, int move, float x, float y, float z, float sx, float sy, float sz, float dur, int giveBack) {
    AmodDemoCamera c;
    int s, m, idx;
    if (API->demo == 0) return;
    memset(&c, 0, sizeof c);
    c.structSize = sizeof c;
    c.position[0] = x; c.position[1] = y; c.position[2] = z;
    c.speed[0] = sx; c.speed[1] = sy; c.speed[2] = sz;
    c.time = dur > 0.001f ? dur : 0.01f;
    c.giveBack = giveBack;
    s = demo_resolve_script(script);
    m = demo_resolve_move(move);
    idx = isView ? API->demo->AddView(SELF, s, m, &c) : API->demo->AddCamera(SELF, s, m, &c);
    if (idx >= 0) g_demo_sel_sub = idx;
}

static MOD_UNUSED void demo_append_time(int script, int move, float pause, float factor, float dur) {
    AmodDemoTime t;
    int idx;
    if (API->demo == 0) return;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    t.pause = pause;
    t.factor = factor;
    t.time = dur;
    idx = API->demo->AddTime(SELF, demo_resolve_script(script), demo_resolve_move(move), &t);
    if (idx >= 0) g_demo_sel_sub = idx;
}

static MOD_UNUSED void demo_set_input(int* horzOut, int* vertOut, int* jumpOut, int horz, int vert, int jump) {
    if (horzOut != 0) *horzOut = horz;
    if (vertOut != 0) *vertOut = vert;
    if (jumpOut != 0) *jumpOut = jump;
    g_demo_input_dirty = 1;
}

static MOD_UNUSED int demo_take_input_dirty(void) {
    int v = g_demo_input_dirty;
    g_demo_input_dirty = 0;
    return v;
}

static int g_demo_ev_kind = 0;
static int g_demo_ev_script = -1;
static int g_demo_ev_move = -1;
static float g_demo_in_pos[3];
static int g_demo_in_horz = 0;
static int g_demo_in_vert = 0;
static int g_demo_in_jump = 0;
static float g_demo_in_sec = 0.0f;

static MOD_UNUSED void __cdecl demo_state_relay(AmodDemoEvent demoEvent, int demoScript, void* user) {
    g_demo_ev_kind = (int)demoEvent;
    g_demo_ev_script = demoScript;
    if (user != 0) ((AmodDemoCallback)user)(demoEvent, demoScript, 0);
}

static MOD_UNUSED void __cdecl demo_move_relay(int demoScript, int demoMove, void* user) {
    g_demo_ev_script = demoScript;
    g_demo_ev_move = demoMove;
    if (user != 0) ((AmodDemoMoveCallback)user)(demoScript, demoMove, 0);
}

static MOD_UNUSED int __cdecl demo_input_relay(const float* demoPos, int* demoHorz, int* demoVert, int* demoJump, float demoSeconds, void* user) {
    if (demoPos != 0) { g_demo_in_pos[0] = demoPos[0]; g_demo_in_pos[1] = demoPos[1]; g_demo_in_pos[2] = demoPos[2]; }
    g_demo_in_horz = demoHorz != 0 ? *demoHorz : 0;
    g_demo_in_vert = demoVert != 0 ? *demoVert : 0;
    g_demo_in_jump = demoJump != 0 ? *demoJump : 0;
    g_demo_in_sec = demoSeconds;
    return user != 0 ? ((AmodDemoInputCallback)user)(demoPos, demoHorz, demoVert, demoJump, demoSeconds, 0) : 0;
}

static MOD_UNUSED int demo_ev_int(int which) {
    if (which == 0) return g_demo_ev_kind;
    if (which == 1) return g_demo_ev_script;
    return g_demo_ev_move;
}

static MOD_UNUSED float demo_in_num(int which) {
    if (which >= 0 && which < 3) return g_demo_in_pos[which];
    return g_demo_in_sec;
}

static MOD_UNUSED int demo_in_int(int which) {
    if (which == 0) return g_demo_in_horz;
    if (which == 1) return g_demo_in_vert;
    return g_demo_in_jump;
}
